// Extrair dados da mensagem recebida
const body = $input.item.json.body;
const data = body.data;

const remoteJid = data.key.remoteJid;
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');
const message = (data.message.conversation || data.message.extendedTextMessage?.text || '').trim();
const pushName = data.pushName || 'cliente';
const instanceName = body.instance || 'kyvvo-test';

// Buscar sessão do Static Data do workflow
const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};

const sessionKey = `session_${phone}`;
let session = staticData.sessions[sessionKey] || { step: 'menu', data: {} };

return {
  phone,
  remoteJid,
  message,
  pushName,
  instanceName,
  session
};

const { phone, remoteJid, message, pushName, instanceName, session } = $input.item.json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const sessionKey = `session_${phone}`;

let responseText = '';
let nextStep = session.step;
let sessionData = { ...session.data };

// STEP: menu principal
if (session.step === 'menu' || message === '0') {
  responseText = `Olá${pushName ? ', ' + pushName.split(' ')[0] : ''}! 👋 Bem-vinda ao Salão Kyvvo!\n\nComo posso te ajudar?\n\n1️⃣ Agendar\n2️⃣ Reagendar\n3️⃣ Cancelar agendamento`;
  nextStep = 'menu_opcao';
  sessionData = {};

// STEP: escolha do menu
} else if (session.step === 'menu_opcao') {
  if (message === '1') {
    responseText = `Qual data você prefere? 📅\n\nResponda no formato DD/MM\nEx: 25/06`;
    nextStep = 'escolher_data';
    sessionData.tipo = 'agendamento';
  } else if (message === '2') {
    responseText = `Para reagendar, por favor informe o número de telefone cadastrado ou a data do agendamento atual.\n\nEx: 20/06`;
    nextStep = 'reagendar_info';
    sessionData.tipo = 'reagendamento';
  } else if (message === '3') {
    responseText = `Para cancelar, informe a data do seu agendamento.\n\nEx: 20/06`;
    nextStep = 'cancelar_info';
    sessionData.tipo = 'cancelamento';
  } else {
    responseText = `Opção inválida. Por favor, escolha:\n\n1️⃣ Agendar\n2️⃣ Reagendar\n3️⃣ Cancelar agendamento`;
    nextStep = 'menu_opcao';
  }

// STEP: escolher data (agendamento)
} else if (session.step === 'escolher_data') {
  const dateRegex = /^(0?[1-9]|[12][0-9]|3[01])\/(0?[1-9]|1[0-2])$/;
  if (dateRegex.test(message)) {
    sessionData.data = message;
    responseText = `Que horário você prefere? ⏰\n\nDisponíveis:\n9h • 10h • 11h\n14h • 15h • 16h • 17h`;
    nextStep = 'escolher_horario';
  } else {
    responseText = `Data inválida. Por favor, use o formato DD/MM.\nEx: 25/06`;
    nextStep = 'escolher_data';
  }

// STEP: escolher horário (agendamento)
} else if (session.step === 'escolher_horario') {
  const horariosValidos = ['9h', '10h', '11h', '14h', '15h', '16h', '17h', '9', '10', '11', '14', '15', '16', '17'];
  const msgNorm = message.toLowerCase().replace('h', '');
  const horariosNorm = ['9', '10', '11', '14', '15', '16', '17'];

  if (horariosNorm.includes(msgNorm)) {
    sessionData.horario = msgNorm + 'h';
    responseText = `✅ Agendamento confirmado!\n\n📅 ${sessionData.data} às ${sessionData.horario}\n\nAté lá! 💜\n\n_Digite 0 para voltar ao menu._`;
    nextStep = 'menu';
    sessionData = {};
  } else {
    responseText = `Horário inválido. Por favor, escolha um dos disponíveis:\n\n9h • 10h • 11h\n14h • 15h • 16h • 17h`;
    nextStep = 'escolher_horario';
  }

// STEP: reagendar
} else if (session.step === 'reagendar_info') {
  responseText = `Entendido! ✅ Nossa equipe vai entrar em contato para confirmar o novo horário.\n\n_Digite 0 para voltar ao menu._`;
  nextStep = 'menu';
  sessionData = {};

// STEP: cancelar
} else if (session.step === 'cancelar_info') {
  responseText = `Cancelamento registrado para ${message}. ✅\n\nSe precisar reagendar, é só nos chamar! 💜\n\n_Digite 0 para voltar ao menu._`;
  nextStep = 'menu';
  sessionData = {};

// FALLBACK
} else {
  responseText = `Olá! 👋 Bem-vinda ao Salão Kyvvo!\n\nComo posso te ajudar?\n\n1️⃣ Agendar\n2️⃣ Reagendar\n3️⃣ Cancelar agendamento`;
  nextStep = 'menu_opcao';
  sessionData = {};
}

// Salvar sessão atualizada no Static Data
staticData.sessions[sessionKey] = { step: nextStep, data: sessionData };

return {
  phone,
  remoteJid,
  instanceName,
  responseText,
  isConfirmed: nextStep === 'menu' && sessionData.tipo === undefined && responseText.includes('confirmado'),
  confirmationData: sessionData
};
